/* data/cs-c/cs-12-05.js - GENERATED by tools/build.py from data/cs/cs-12-05.json. Questions are the board's; answers are our own words. Do not edit. */
(window.CS_C = window.CS_C || {})["cs-12-05"] = [{"id":"cs-12-05-01","kind":"short","q":"What is microprocessor ?","marks":3,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.1"],"model":[{"t":"A microprocessor is a single chip (an IC) that works as the central processing unit (CPU) of a computer.","m":1},{"t":"It reads the instructions of a program from memory, decodes them, and does the arithmetic, logic and control work.","m":1},{"t":"It is made with VLSI technology. Examples: Intel 8085, 8086.","m":1}]},{"id":"cs-12-05-02","kind":"short","q":"What is LSI and VLSI ?","marks":3,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.2"],"model":[{"t":"LSI means Large Scale Integration: one chip holds thousands of transistors (gates).","m":1},{"t":"VLSI means Very Large Scale Integration: one chip holds hundreds of thousands to millions of transistors.","m":1},{"t":"Microprocessors are built with LSI and VLSI technology, which makes them small, cheap and fast.","m":1}]},{"id":"cs-12-05-03","kind":"short","q":"Which was the first microprocessor?","marks":3,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.3"],"model":[{"t":"The first microprocessor was the Intel 4004, made by Intel in 1971.","m":1},{"t":"It was a 4-bit microprocessor, used in a calculator.","m":1},{"t":"The first 8-bit microprocessors that followed were the Intel 8008 and 8080.","m":1}]},{"id":"cs-12-05-04","kind":"short","q":"What do you mean by upward software compatibility?","marks":3,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.4"],"model":[{"t":"Upward software compatibility means that a program written for an older microprocessor of a family runs on the newer microprocessor of the same family without any change.","m":1},{"t":"Example: programs written for the 8080 also run on the 8085.","m":1},{"t":"It saves the work and the money already spent on the old software.","m":1}]},{"id":"cs-12-05-05","kind":"prog","q":"Draw a labelled block diagram of generic microprocessor.","marks":5,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.5"],"model":[{"t":"The diagram has the main blocks: ALU, accumulator, flag (status) register and general purpose registers.","m":1},{"t":"The instruction register and instruction decoder, and the program counter and stack pointer, are shown.","m":1},{"t":"The timing and control unit is shown with its control signals.","m":1},{"t":"The blocks are joined by the internal data bus, and the data, address and control buses go outside.","m":1},{"t":"The diagram is neat and every block is labelled.","m":1}],"code":"            Address bus (16)  <-----------------+\n                                                  |\n +----------+   +------------------+   +-------------+\n |  Program |   |  Stack pointer   |   | Address     |\n |  counter |   |  (SP)            |   | buffer      |\n +----+-----+   +--------+---------+   +------+------+\n      |                  |                    |\n ================== internal data bus ===================\n      |        |                 |           |\n +----+----+ +-+---------+  +----+-----+ +---+-------------+\n |   ALU   | |Accumulator|  | General  | | Instruction reg.|\n +----+----+ +-----------+  | registers| |  -> Decoder     |\n      |                     +----------+ +---+-------------+\n +----+----+                                  |\n | Flag    |                      +-----------+-----------+\n | register|                      |  Timing and control   |--> control signals\n +---------+                      +-----------------------+\n      |\n Data bus (8)  <-->"},{"id":"cs-12-05-06","kind":"short","q":"Name six functional units in generic microprocessor.","marks":3,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.6"],"model":[{"t":"Arithmetic and logic unit (ALU) and the accumulator.","m":1},{"t":"Registers: general purpose registers, the flag register, the program counter and the stack pointer.","m":1},{"t":"Instruction register with the instruction decoder, and the timing and control unit.","m":1}]},{"id":"cs-12-05-07","kind":"short","q":"What functional unit is found between data bus and intimal bus of generic microprocessor?","marks":3,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.7"],"model":[{"t":"The data buffer (bus buffer) is found between the data bus and the internal data bus.","m":1},{"t":"It is a bi-directional, three-state buffer: it passes data into the microprocessor and out of it.","m":1},{"t":"It also keeps the microprocessor away from the external bus when it is not in use.","m":1}]},{"id":"cs-12-05-08","kind":"short","q":"What are control signals of generic microprocessor ?","marks":4,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.8"],"model":[{"t":"Control signals are the signals made by the timing and control unit to run all the parts in order.","m":1},{"t":"Memory read (RD) and memory write (WR) tell memory whether to give or to take data.","m":1},{"t":"I/O read and I/O write do the same for input and output devices.","m":1},{"t":"Others: clock, reset, interrupt request and acknowledge, ready and hold.","m":1}]},{"id":"cs-12-05-09","kind":"short","q":"What is purpose of program counter and stack pointer in generic microprocessor?","marks":4,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.9"],"model":[{"t":"The program counter (PC) holds the address of the next instruction to be fetched from memory.","m":1},{"t":"It increases by one after each fetch, so that the instructions are done in order. A jump changes it.","m":1},{"t":"The stack pointer (SP) holds the address of the top of the stack, a part of memory used for storing return addresses and data.","m":1},{"t":"It is changed by PUSH, POP, CALL and RET, and it is 16 bits wide in 8085.","m":1}]},{"id":"cs-12-05-10","kind":"short","q":"What is INTR ?","marks":3,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.10"],"model":[{"t":"INTR is the Interrupt Request input pin of the 8085.","m":1},{"t":"An outside device sends a signal on it to ask the microprocessor to stop its work and serve the device.","m":1},{"t":"It is a maskable interrupt of the lowest priority, and it needs the interrupt acknowledge signal INTA.","m":1}]},{"id":"cs-12-05-12","kind":"short","q":"What is bus ? State different types of buses in generic microprocessor.","marks":4,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.12"],"model":[{"t":"A bus is a group of wires that carries signals (data, addresses or control information) between the parts of the computer.","m":1},{"t":"Data bus: carries data and works in both directions (8 bits in 8085).","m":1},{"t":"Address bus: carries the address of a memory location or of a device, and works one way (16 bits in 8085).","m":1},{"t":"Control bus: carries the control signals such as read and write.","m":1}]},{"id":"cs-12-05-13","kind":"short","q":"What is ALU ?","marks":3,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.13"],"model":[{"t":"ALU is the Arithmetic and Logic Unit, the part of the microprocessor that does the calculations.","m":1},{"t":"It does arithmetic work (add, subtract) and logic work (AND, OR, XOR, compare, complement).","m":1},{"t":"It works with the accumulator, and it sets the flags that tell about the result.","m":1}]},{"id":"cs-12-05-14","kind":"short","q":"Write the function of instruction register and decoder in generic microprocessor.","marks":4,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.14"],"model":[{"t":"The instruction register holds the opcode (the code of the instruction) that has just been fetched from memory.","m":1},{"t":"The instruction decoder reads the opcode in the instruction register and finds out which operation is asked.","m":1},{"t":"It passes the result to the timing and control unit.","m":1},{"t":"The control unit then makes the control signals to do that instruction.","m":1}]},{"id":"cs-12-05-15","kind":"short","q":"What is instruction cycle?","marks":3,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.15"],"model":[{"t":"The instruction cycle is the time the microprocessor takes to fetch one instruction from memory and to execute it.","m":1},{"t":"It is made of a fetch cycle (get the opcode) and an execute cycle (do the work).","m":1},{"t":"It may take one or more machine cycles, and each machine cycle takes some T-states (clock periods).","m":1}]},{"id":"cs-12-05-16","kind":"short","q":"How much memory can be addressed by 8085? Why?","marks":3,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.16"],"model":[{"t":"8085 can address 64 KB of memory (65,536 locations).","m":1},{"t":"It has a 16-bit address bus, and 16 address lines can make 2 to the power 16 = 65,536 different addresses.","m":1},{"t":"The addresses run from 0000H to FFFFH.","m":1}]},{"id":"cs-12-05-17","kind":"short","q":"What do you mean by multiplexed address data bus?","marks":4,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.17"],"model":[{"t":"In 8085 the pins AD0 to AD7 are used for two jobs, at different times: as the lower 8 address lines and as the 8 data lines.","m":1},{"t":"This is called a multiplexed address/data bus. It saves pins, so that the chip can have only 40 pins.","m":1},{"t":"The pins carry the low address byte in the first clock period of a machine cycle, and data afterwards.","m":1},{"t":"The ALE signal tells when the pins carry an address, so that an external latch can keep it.","m":1}]},{"id":"cs-12-05-18","kind":"short","q":"Which are control signal pins on 8085?","marks":3,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.18"],"model":[{"t":"ALE (address latch enable), RD (read) and WR (write) are the control signals.","m":1},{"t":"IO/M tells whether the operation is for an I/O device or for memory.","m":1},{"t":"The status signals S0 and S1 show the type of the machine cycle.","m":1}]},{"id":"cs-12-05-19","kind":"short","q":"What is ALE? Explain its use.","marks":4,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.19"],"model":[{"t":"ALE means Address Latch Enable. It is an output signal of the 8085.","m":1},{"t":"It goes high in the first clock period of every machine cycle, when AD0 to AD7 carry the lower byte of the address.","m":1},{"t":"An external latch (such as 74LS373) uses it to catch and hold that address byte.","m":1},{"t":"The pins then carry data, and the full 16-bit address stays available.","m":1}]},{"id":"cs-12-05-20","kind":"short","q":"Which are status signals of 8085?","marks":3,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.20"],"model":[{"t":"IO/M (low for memory, high for I/O device), S1 and S0.","m":1},{"t":"S1 and S0 together tell the type of operation: 00 halt, 01 write, 10 read, 11 opcode fetch.","m":1},{"t":"They show what the microprocessor is doing in the present machine cycle.","m":1}]},{"id":"cs-12-05-21","kind":"short","q":"List machine cycle types for 8085.","marks":4,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.21"],"model":[{"t":"Opcode fetch cycle (to get the instruction) and memory read cycle.","m":1},{"t":"Memory write cycle.","m":1},{"t":"I/O read cycle and I/O write cycle.","m":1},{"t":"Interrupt acknowledge cycle (to serve an interrupt) and bus idle cycle.","m":1}]},{"id":"cs-12-05-22","kind":"short","q":"What is crystal frequency and operating frequency of 8085?","marks":3,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.22"],"model":[{"t":"A crystal connected to pins X1 and X2 gives the basic frequency, up to 6 MHz in an 8085 system.","m":1},{"t":"The microprocessor divides it by 2 inside, so the operating (internal clock) frequency is half of the crystal frequency.","m":1},{"t":"Example: a 6 MHz crystal gives a 3 MHz operating frequency.","m":1}]},{"id":"cs-12-05-23","kind":"short","q":"What is purpose of interrupts?","marks":3,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.23"],"model":[{"t":"An interrupt is a signal that asks the microprocessor to stop its present work for a while and to do an urgent job.","m":1},{"t":"It lets the microprocessor serve the input and output devices only when they need it, so it need not keep checking them.","m":1},{"t":"After the service routine the microprocessor goes back to the program it was running.","m":1}]},{"id":"cs-12-05-24","kind":"short","q":"List the interrupt signals along with priority for 8085.","marks":4,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.24"],"model":[{"t":"TRAP: highest priority, not maskable.","m":1},{"t":"RST 7.5: second priority. RST 6.5: third priority.","m":1},{"t":"RST 5.5: fourth priority.","m":1},{"t":"INTR: lowest priority. All except TRAP can be masked.","m":1}]},{"id":"cs-12-05-25","kind":"short","q":"What is purpose of SID and SOD?","marks":3,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.25"],"model":[{"t":"SID is the Serial Input Data pin. The RIM instruction reads the bit on it into bit 7 of the accumulator.","m":1},{"t":"SOD is the Serial Output Data pin. The SIM instruction sends bit 7 of the accumulator to it.","m":1},{"t":"They give serial data transfer of one bit at a time, without extra chips.","m":1}]},{"id":"cs-12-05-26","kind":"prog","q":"Draw pinout diagram for 8085.","marks":5,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.26"],"model":[{"t":"The 40-pin chip is drawn with pins numbered from 1 to 40 and a notch at the top.","m":1},{"t":"Power: pin 40 is Vcc (+5 V) and pin 20 is Vss (ground).","m":1},{"t":"AD0 to AD7 (pins 12 to 19), A8 to A15 (pins 21 to 28), ALE, RD, WR and IO/M are shown.","m":1},{"t":"The interrupt pins (TRAP, RST 7.5, 6.5, 5.5, INTR, INTA) and SID and SOD are shown.","m":1},{"t":"RESET IN, RESET OUT, HOLD, HLDA, READY, CLK OUT, X1 and X2 are shown.","m":1}],"code":"            +-------\\_/-------+\n   X1   1 - |                  | - 40  Vcc\n   X2   2 - |                  | - 39  HOLD\n RESET OUT 3 - |                | - 38  HLDA\n   SOD  4 - |                  | - 37  CLK OUT\n   SID  5 - |                  | - 36  RESET IN\n  TRAP  6 - |       8085       | - 35  READY\n RST7.5 7 - |                  | - 34  IO/M\n RST6.5 8 - |                  | - 33  S1\n RST5.5 9 - |                  | - 32  RD\n  INTR 10 - |                  | - 31  WR\n  INTA 11 - |                  | - 30  ALE\n   AD0 12 - |                  | - 29  S0\n   AD1 13 - |                  | - 28  A15\n   AD2 14 - |                  | - 27  A14\n   AD3 15 - |                  | - 26  A13\n   AD4 16 - |                  | - 25  A12\n   AD5 17 - |                  | - 24  A11\n   AD6 18 - |                  | - 23  A10\n   AD7 19 - |                  | - 22  A9\n   Vss 20 - |                  | - 21  A8\n            +------------------+"},{"id":"cs-12-05-27","kind":"prog","q":"Draw labelled functional block diagram for 8085.","marks":5,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.27"],"model":[{"t":"The ALU, accumulator, temporary register and the flag register are shown.","m":1},{"t":"The general purpose registers B, C, D, E, H, L, and W and Z (temporary) are shown with the program counter and the stack pointer.","m":1},{"t":"The instruction register, the decoder and the timing and control unit are shown.","m":1},{"t":"The interrupt control, serial I/O control and the address and data buffers are shown.","m":1},{"t":"The blocks are joined with the internal bus, and the diagram is labelled.","m":1}],"code":"  +----------------------------------------------------------+\n  |                   8085 microprocessor                    |\n  |                                                          |\n  |  Accumulator (A)   Temp reg     Flag reg (S Z AC P CY)   |\n  |        \\             |              /                    |\n  |         +----------- ALU ------------+                    |\n  |                                                          |\n  |  B  C     D  E     H  L     W  Z (temporary)             |\n  |  Stack pointer (16)    Program counter (16)              |\n  |  Incrementer / decrementer address latch                 |\n  |                                                          |\n  |  Instruction register -> Instruction decoder             |\n  |  Timing and control   Interrupt control   Serial I/O     |\n  |  (ALE RD WR IO/M S0 S1)  (TRAP, RST, INTR) (SID, SOD)   |\n  +------+-------------------+------------------+------------+\n   Address buffer (A8-A15)  Data/address buffer (AD0-AD7)"},{"id":"cs-12-05-28","kind":"short","q":"What is flag? List flags for 8085.","marks":4,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.28"],"model":[{"t":"A flag is a single bit (a flip-flop) that shows the result of the last arithmetic or logic operation.","m":1},{"t":"The 8085 has five flags: Sign (S), Zero (Z), Auxiliary carry (AC), Parity (P) and Carry (CY).","m":1},{"t":"S is 1 if the result is negative; Z is 1 if the result is zero; AC is 1 if there is a carry from bit 3 to bit 4.","m":1},{"t":"P is 1 if the result has an even number of 1s; CY is 1 if there is a carry out of bit 7.","m":1}]},{"id":"cs-12-05-29","kind":"short","q":"Two numbers 10H and 28H are added in accumulator. What is effect of this operation on flags?","marks":3,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.29"],"model":[{"t":"10H + 28H = 38H = 0011 1000. The accumulator holds 38H.","m":1},{"t":"Sign flag S = 0 (bit 7 is 0) and Zero flag Z = 0 (the result is not zero). Carry CY = 0 (no carry out of bit 7).","m":1},{"t":"Auxiliary carry AC = 0 (0 + 8 gives no carry from bit 3), and parity P = 0, because 38H has three 1s, an odd number.","m":1}]},{"id":"cs-12-05-30","kind":"short","q":"What is register? List registers in 8085.","marks":3,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.30"],"model":[{"t":"A register is a small, fast memory location inside the microprocessor that holds data or an address for a short time.","m":1},{"t":"The 8-bit registers: A (accumulator), B, C, D, E, H, L and the flag register; W and Z are temporary registers.","m":1},{"t":"The 16-bit registers: the program counter (PC) and the stack pointer (SP). B-C, D-E and H-L can be used as pairs.","m":1}]},{"id":"cs-12-05-31","kind":"short","q":"Explain purpose of program counter and stack pointer for 8085.","marks":4,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.31"],"model":[{"t":"The program counter is a 16-bit register that holds the address of the next instruction to be fetched.","m":1},{"t":"After each fetch it is increased automatically; a jump or call puts a new address in it.","m":1},{"t":"The stack pointer is a 16-bit register that holds the address of the top of the stack in memory.","m":1},{"t":"The stack saves return addresses (CALL, RST) and data (PUSH); the SP goes down on PUSH and up on POP.","m":1}]},{"id":"cs-12-05-m32a","kind":"mcq","q":"The program counter is a 16-bit storage area reserved for .................","marks":1,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.32(a)"],"options":["Addresses","Instructions","Data","none of these"],"ans":0,"why":"The program counter holds the 16-bit address of the next instruction, not the instruction itself."},{"id":"cs-12-05-m32b","kind":"mcq","q":"The read and write control signals are generated by .......... section MPU.","marks":1,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.32(b)"],"options":["ALU","Timing and control section","Registers","PC"],"ans":1,"why":"The timing and control section makes all the control signals, such as RD and WR."},{"id":"cs-12-05-m32c","kind":"mcq","q":"The first microprocessor was ..............","marks":1,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.32(c)"],"options":["Intel 4004","8080","8085","4008"],"ans":0,"why":"The Intel 4004 (1971) was the first microprocessor."},{"id":"cs-12-05-m32d","kind":"mcq","q":"H and L are .................","marks":1,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.32(d)"],"options":["data / address register","data register","Address register","none of these"],"ans":0,"why":"H and L are general purpose registers: they can hold data, and as the HL pair they also hold a memory address."},{"id":"cs-12-05-m32e","kind":"mcq","q":"ALU is ..........","marks":1,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.32(e)"],"options":["Arithmetic and logic unit","Accumulator","Automatic control unit","none of these"],"ans":0,"why":"ALU stands for Arithmetic and Logic Unit."},{"id":"cs-12-05-m32f","kind":"mcq","q":"Stack pointer holds ...............","marks":1,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.32(f)"],"options":["16 bit address","16 bit data","8 bit address","8 bit data"],"ans":0,"why":"The stack pointer holds the 16-bit address of the top of the stack."},{"id":"cs-12-05-m32g","kind":"mcq","q":"8085 is .......... pin IC.","marks":1,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.32(g)"],"options":["45","40","35","20"],"ans":1,"why":"The 8085 is a 40-pin IC."},{"id":"cs-12-05-m32h","kind":"mcq","q":"8085 microprocessor uses ............ V power supply.","marks":1,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.32(h)"],"options":["+5","-5","12V","-12V"],"ans":0,"why":"The 8085 works on a single +5 V supply."},{"id":"cs-12-05-m32i","kind":"mcq","q":"The address / data bus in 8085 is ...........","marks":1,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.32(i)"],"options":["multiplexed","demultiplexed","decoded","loded"],"ans":0,"why":"AD0 to AD7 carry the low address byte and the data at different times, so the bus is multiplexed."},{"id":"cs-12-05-m32j","kind":"mcq","q":"The SID pin handles ........... bit (s) at a time","marks":1,"src":["Guide ch.5 Introduction to Microprocessors and Organisation of 8085, Q.32(j)"],"options":["8","1","4","2"],"ans":1,"why":"SID is a serial input line, so it handles one bit at a time."},{"id":"cs-12-05-p901","kind":"mcq","q":"8085 Microprocessor consists of .......... general purpose registers.","marks":1,"src":["HSC March 2022 Paper II, Q.1A(a)"],"options":["4","6","8","16"],"ans":1,"why":"The general purpose registers of the 8085 are B, C, D, E, H and L: six registers (the accumulator is counted separately)."},{"id":"cs-12-05-p902","kind":"mcq","q":"The intrrupt.......... is not vectored.","marks":1,"src":["HSC March 2023 Paper II, Q.1A(b)"],"options":["INTR","TRAP","RST 7.5","RST 6.5"],"ans":0,"why":"TRAP, RST 7.5, RST 6.5 and RST 5.5 jump to a fixed address (vectored). INTR is not vectored: the device must supply the instruction (an RST or CALL)."},{"id":"cs-12-05-p903","kind":"mcq","q":"The invalid register pair in 8085 Microprocessor is 1","marks":1,"src":["HSC March 2024 Paper II, Q.1A(a)"],"options":["BC","HL","SP","DE"],"ans":2,"why":"The board key gives SP. The register pairs of the 8085 are BC, DE and HL (SP is the stack pointer; PUSH and POP use PSW with them). Check this one with your teacher if it is asked another way."},{"id":"cs-12-05-p904","kind":"short","q":"Explain following registers of 8085 Microprocessor :\ni) Instruction Decoder\nii) Temporary Register\niii) Stack Pointer","marks":3,"src":["HSC March 2022 Paper II, Q.1B(a)"],"model":[{"t":"Instruction decoder: the opcode that is fetched is kept in the instruction register. The decoder decodes it and tells the timing and control unit what operation to do.","m":1},{"t":"Temporary register: an 8-bit register inside the 8085 that the programmer cannot use. It holds one operand of the ALU during an operation (the other one is in the accumulator).","m":1},{"t":"Stack pointer: a 16-bit register that holds the address of the top of the stack. PUSH, POP, CALL and RET change it.","m":1}]},{"id":"cs-12-05-p905","kind":"short","q":"What do you mean by Interrupt ? Explain Sofware Interrupt.","marks":3,"src":["HSC March 2022 Paper II, Q.1B(b)"],"model":[{"t":"An interrupt is a signal that makes the processor stop its present job, serve the device or event, and then return to the job.","m":1},{"t":"A software interrupt is raised by an instruction in the program, not by an outside signal. In the 8085 these are the eight RST instructions, RST 0 to RST 7.","m":1},{"t":"RST n works like a one byte CALL: it saves the program counter on the stack and jumps to the address 8 times n (RST 1 goes to 0008H, RST 7 to 0038H).","m":1}]},{"id":"cs-12-05-p906","kind":"short","q":"Explain following pins of 8085 Microprocessor :\ni) STD\nii) HOLD\niii) IO / M","marks":3,"src":["HSC March 2022 Paper II, Q.2A(c)"],"model":[{"t":"The first pin is printed as STD. The pin meant is SID (serial input data): one bit of serial data comes in here, and the RIM instruction reads it into bit D7 of the accumulator.","m":1},{"t":"HOLD: an input. A device such as a DMA controller asks the 8085 to give the buses to it. The 8085 answers with HLDA and releases the buses.","m":1},{"t":"IO/M: an output status signal. High means the operation is on an I/O device, low means it is on memory.","m":1}]},{"id":"cs-12-05-p907","kind":"short","q":"What is Microprocessor ? Write features of 8085 Microprocessor.","marks":3,"src":["HSC March 2022 Paper II, Q.4A(b)"],"model":[{"t":"A microprocessor is a programmable chip (IC) that contains the ALU, the registers and the control unit of a computer: it is the CPU on one chip.","m":1},{"t":"Features: 8-bit processor with an 8-bit data bus; 16-bit address bus, so it can address 64 KB of memory.","m":1},{"t":"Other features: 40 pin IC with a single +5 V supply, a clock of 3 MHz, five hardware interrupts, serial input and output pins (SID, SOD), and an instruction set of 74 instructions.","m":1}]},{"id":"cs-12-05-p908","kind":"short","q":"Write the function of following pins in 8085 Microprocessor.\ni) WR\nii) RESET IN\niii) READY","marks":3,"src":["HSC March 2023 Paper II, Q.2A(b)"],"model":[{"t":"WR (active low): an output. When it is low, the 8085 is writing, that is, the data on the data bus is to be stored in the memory or the I/O device.","m":1},{"t":"RESET IN (active low, printed RESTIN): an input. When it goes low, the program counter is cleared to 0000H and the processor starts again from there.","m":1},{"t":"READY: an input. The 8085 waits (wait states) until a slow memory or device makes READY high, so the data transfer is completed.","m":1}]},{"id":"cs-12-05-p909","kind":"short","q":"Write any three points which specifies Accumulator of 8085 micro procesor as a special purpose register.","marks":3,"src":["HSC March 2023 Paper II, Q.4A(a)"],"model":[{"t":"The accumulator is an 8-bit register. In arithmetic and logic operations one operand is always taken from it.","m":1},{"t":"The result of the operation is stored back in the accumulator.","m":1},{"t":"Data for the input and output instructions (IN, OUT) passes through it, and LDA and STA move data between it and memory. It is also the register that the flags describe.","m":1}]},{"id":"cs-12-05-p910","kind":"short","q":"Answer the following with respect to hardware interrupts of 8085 Microprocesser.\ni) List all interrupts\nii) Specify the higher and lowest priority interrupt\niii) Soecify whether maskable or Non-maskable interrupt.","marks":3,"src":["HSC March 2023 Paper II, Q.4A(c)"],"model":[{"t":"The hardware interrupts of the 8085 are TRAP, RST 7.5, RST 6.5, RST 5.5 and INTR.","m":1},{"t":"TRAP has the highest priority and INTR has the lowest priority. The order is TRAP, RST 7.5, RST 6.5, RST 5.5, INTR.","m":1},{"t":"TRAP is non-maskable. RST 7.5, RST 6.5, RST 5.5 and INTR are maskable (they can be disabled by the program).","m":1}]},{"id":"cs-12-05-p911","kind":"short","q":"Contents of flag register of 8085 Microprocessor is 55H. Write its bit pattern and give interpretations.","marks":3,"src":["HSC March 2024 Paper II, Q.1B(a)"],"model":[{"t":"55H = 0101 0101. The flag register has the bits D7 D6 D5 D4 D3 D2 D1 D0 = S Z X AC X P X CY (X means not used).","m":1},{"t":"So S = 0 (the result is positive), Z = 1 (the result is zero), AC = 1 (there was a carry from bit 3 to bit 4).","m":1},{"t":"P = 1 (the result has even parity), CY = 1 (there was a carry out of bit 7). The unused bits are 0 and 0 and 0.","m":1}]},{"id":"cs-12-05-p912","kind":"prog","q":"Explain the organisation of ALU with the help of block diagram.","marks":3,"src":["HSC March 2024 Paper II, Q.1B(b)"],"model":[{"t":"The ALU (arithmetic and logic unit) does the arithmetic operations (add, subtract) and the logic operations (AND, OR, XOR, compare, rotate).","m":1},{"t":"It has two inputs: one from the accumulator and one from the temporary register. The result goes back to the accumulator.","m":1},{"t":"The flag register is attached to the ALU and records the result: S, Z, AC, P and CY. All parts are joined by the internal data bus.","m":1}],"code":"      Internal data bus\n   ------+-----------+----------\n         |           |\n   +-----v-----+  +--v-------------+\n   |Accumulator|  |Temporary reg.  |\n   +-----+-----+  +--+-------------+\n         |           |\n      +--v-----------v--+        +-----------+\n      |       ALU       |------->| Flag reg. |\n      +--------+--------+        | S Z AC P CY|\n               |                 +-----------+\n      result back to accumulator"},{"id":"cs-12-05-p913","kind":"short","q":"Explain the function of following pins of 8085 Microprocessor:\ni) RD\nii) HOLD\niii) RST 7.5\niv) INTA","marks":4,"src":["HSC March 2024 Paper II, Q.2B(a)"],"model":[{"t":"RD (active low): an output. When low, the 8085 is reading, so the selected memory or I/O device may put data on the data bus.","m":1},{"t":"HOLD: an input. Another device (for example a DMA controller) asks the 8085 to release the buses. The 8085 answers on HLDA.","m":1},{"t":"RST 7.5: a maskable, vectored interrupt input, triggered by a rising edge. It jumps to the address 003CH and has the highest priority after TRAP.","m":1},{"t":"INTA (active low): an output. The 8085 sends it as the answer to INTR, so that the device can put an instruction (RST or CALL) on the data bus.","m":1}]},{"id":"cs-12-05-p914","kind":"short","q":"What is Bus? Explain address Bus and Data Bus of 8085 Microprocessor.","marks":3,"src":["HSC March 2024 Paper II, Q.3A(b)"],"model":[{"t":"A bus is a group of wires that carries signals (addresses, data or control) between the parts of a computer.","m":1},{"t":"Address bus: 16 lines A15 to A0, one way (from the processor). The high bytes A15 to A8 have their own pins, the low byte is multiplexed with data (AD7 to AD0). It can address 2 to the power 16 = 64 KB.","m":1},{"t":"Data bus: 8 lines D7 to D0, two way. It carries the data between the processor, the memory and the I/O devices. It shares the pins AD7 to AD0 with the low address byte.","m":1}]},{"id":"cs-12-05-p915","kind":"short","q":"Differentiate between Hardware and Software interrupts of 8085 Microprocessor. (Any three points)","marks":3,"src":["HSC March 2024 Paper II, Q.4A(a)"],"model":[{"t":"Source: a hardware interrupt comes from an outside device on a pin (TRAP, RST 7.5, 6.5, 5.5, INTR). A software interrupt is made by an instruction in the program (RST 0 to RST 7).","m":1},{"t":"Timing: a hardware interrupt can come at any time; a software interrupt comes only at the place where the instruction is written.","m":1},{"t":"Control: hardware interrupts (except TRAP) can be masked; a software interrupt cannot be masked. Hardware interrupts have a priority, software interrupts do not.","m":1}]}];
